 #[test]fn audio_windows_root_startup_real_cookie_entropy_precedes_dispatch_and_matches6_native_startup_banks_after_cookie_input_transition(){let p=fixture();let mut count=0;for row in p["cases"].as_array().unwrap().iter().filter(|v|v["layout"]=="all"&&v["failure"]=="none"){let mut c=prepare(&p,row);let old=get(&c.memory,&c.dead,crate::audio_security_cookie::COOKIE,4).unwrap();c.memory.insert(crate::audio_security_cookie::COMPLEMENT,Memory{reference:crate::audio_security_cookie::COMPLEMENT,raw:vec![0xa5;4]});let report=c.services.inner.heap.report();let startup=initialize_with_cookie(c,Some(retire),0x4001fff8,[0,0],&mut crate::audio_security_cookie::WindowsEntropy).unwrap();assert_eq!(startup.status,1);let record=startup.initial_record.unwrap();startup.context.with(|c|{let cookie=get(&c.memory,&c.dead,crate::audio_security_cookie::COOKIE,4).unwrap();assert_ne!(cookie,crate::audio_security_cookie::DEFAULT);assert_ne!(cookie&0xffff0000,0);assert_eq!(get(&c.memory,&c.dead,crate::audio_security_cookie::COMPLEMENT,4).unwrap(),!cookie);if old!=crate::audio_security_cookie::DEFAULT&&old&0xffff0000!=0{assert_eq!(cookie,old);}let mut normalized=row.clone();normalized["cookie"]=serde_json::json!(cookie);let region=p["regions"].as_array().unwrap().iter().find(|v|v["reference"]==crate::audio_security_cookie::COOKIE as u64).unwrap();normalized["after"][region["name"].as_str().unwrap()]=serde_json::json!(cookie.to_le_bytes().iter().map(|v|format!("{v:02x}")).collect::<String>());compare(&p,&normalized,View{memory:&c.memory,dead:&c.dead,services:&c.services},Some(record));}).unwrap();assert_eq!(startup.current().unwrap(),record);startup.shutdown().unwrap();assert_eq!((report.allocations(),report.frees()),(1,1));assert!(report.failures().is_empty());count+=1;}assert_eq!(count,6);}
