 #[test]fn audio_windows_root_startup_cookie_guard_rejects_foreign_slot_and_missing_output_storage_without_entropy_calls(){let p=fixture();let row=p["cases"].as_array().unwrap().iter().find(|v|v["layout"]=="all"&&v["failure"]=="none").unwrap();for foreign in[false,true]{let mut c=prepare(&p,row);if foreign{put(&mut c.memory,&c.dead,0x12230cc,4,7).unwrap();}let report=c.services.inner.heap.report();assert!(initialize_with_cookie(c,Some(retire),0x4001fff8,[0,0],&mut NoEntropy).is_err());assert_eq!((report.allocations(),report.frees()),(0,0));assert!(report.failures().is_empty());}}
